public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("The file cannot be null.");
    }
    file.deleteOnExit();
}

if (file.isDirectory()) {
    File[] files = file.listFiles();
    if (files != null) {
        for (File f : files) {
            forceDeleteOnExit(f);
        }
    }
}

